    text: a.textContent.trim(),
    href: a.href
  })).filter(l => l.text.toLowerCase().includes('tv') || l.text.toLowerCase().includes('popular') || l.href.includes('tv'));
  return { tvLink: tvLink ? { text: tvLink.textContent, href: tvLink.href } : null, allLinks };
});

