const tabId = 1148881640;

// Close the modal dialog if present
const closeButton = await browserjs(tabId, () => {
  const closeBtn = document.querySelector('button[aria-label="Close"]') || document.querySelector('dialog button');
  if (closeBtn) {
    closeBtn.click();
    return true;
  }
  return false;
});
console.log("Modal closed:", closeButton);

// Check filter buttons and sort options
const filterData = await browserjs(tabId, () => {
  const buttons = Array.from(document.querySelectorAll('button, select, [role="button"], [data-qa]')).map(el => ({
    tag: el.tagName,
    text: el.textContent.trim().replace(/\s+/g, ' '),
    qa: el.getAttribute('data-qa'),
    ariaLabel: el.getAttribute('aria-label')
  })).filter(b => b.text.length > 0 && b.text.length < 50);
  return buttons;
});
console.log(filterData);

const tabId = 1148881640;

const shows = await browserjs(tabId, () => {
  const cards = document.querySelectorAll('[data-qa="discovery-media-list-item"]');
  const results = [];
  cards.forEach(card => {
    const title = card.querySelector('[data-qa="discovery-media-list-item-title"]')?.textContent?.trim();
    const tomatometer = card.querySelector('score-pairs')?.getAttribute('criticsscore') || 
                        card.querySelector('[data-qa="tomatometer"]')?.textContent?.trim();
    const audienceScore = card.querySelector('score-pairs')?.getAttribute('audiencescore') ||
                          card.querySelector('[data-qa="popcornmeter"]')?.textContent?.trim();
    const date = card.querySelector('[data-qa="discovery-media-list-item-start-date"]')?.textContent?.trim();
    results.push({ title, tomatometer, audienceScore, date });
  });
  return results;
});

console.log(JSON.stringify(shows, null, 2));

const tabId = 1148881640;

const sampleHtml = await browserjs(tabId, () => {
  const container = document.querySelector('discovery-media-list') || document.querySelector('[data-qa="discovery-media-list"]');
  const items = Array.from(document.querySelectorAll('[data-qa="discovery-media-list-item"]'));
  if (items.length > 0) {
    return items[0].outerHTML;
  }
  return container ? container.outerHTML.slice(0, 1000) : 'not found';
});

console.log(sampleHtml);

const tabId = 1148881640;

const tiles = await browserjs(tabId, () => {
  const links = Array.from(document.querySelectorAll('[data-qa="discovery-media-list-item-caption"]'));
  return links.map(a => {
    const title = a.querySelector('[data-qa="discovery-media-list-item-title"]')?.textContent?.trim();
    const date = a.querySelector('[data-qa="discovery-media-list-item-start-date"]')?.textContent?.trim();
    const fullText = a.textContent?.trim().replace(/\s+/g, ' ');
    const href = a.getAttribute('href');
    return { title, date, fullText, href };
  });
});

console.log(JSON.stringify(tiles, null, 2));

